<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import axios from 'axios'
const base = '/api/v1/admin/audience'
const crm = base + '/crm'
const tab = ref('users'), busy = ref(false), loading = ref(false), error = ref(''), notice = ref('')
const users = ref<any[]>([]), total = ref(0), offset = ref(0), search = ref('')
const status = ref('all'), login = ref('all'), subscription = ref('all')
const overview = ref<any>(null), modules = ref<any[]>([]), plans = ref<any[]>([]), promos = ref<any[]>([])
const segments = ref<any[]>([]), campaigns = ref<any[]>([]), genres = ref<any[]>([])
const profile = ref<any>(null), planId = ref(''), banReason = ref(''), drawer = ref<HTMLElement>()
const moduleForm = ref({ name: '', description: '' }), showModule = ref(false)
const plan = ref<any>({ code: '', title: '', billing_period_days: 30, price_amount: 0, currency: 'USD', is_active: true, entitlements: [] })
const showPlan = ref(false)
const promo = ref({ code: '', label: '', plan_id: '', duration_days: 30, max_redemptions: 100, expires_at: '' })
const showPromo = ref(false)
const catalogKind = ref('movie'), catalogSearch = ref(''), catalogRows = ref<any[]>([]), catalogOffset = ref(0)
const segment = ref<any>({ title: '', activity: '', genre: '', movie_id: '', subscription_status: '', can_send_telegram_msg: true })
const movieSearch = ref(''), movieMatches = ref<any[]>([]), segmentCount = ref<number | null>(null)
const campaign = ref<any>({ title: '', segment_id: '', text: '', parse_mode: 'HTML', buttons: [] })
const confirmAction = ref<{ title: string; text: string; run: () => Promise<any> } | null>(null)
const activePlans = computed(() => plans.value.filter(p => p.is_active))
const kpis = [['total', 'Всего пользователей'], ['active_7d', 'Активны за 7 дней'], ['subscribed', 'С подпиской'], ['telegram', 'Доступны в Telegram'], ['blocked', 'Заблокированы']]
let generation = 0, searchTimer: ReturnType<typeof setTimeout> | undefined, catalogTimer: ReturnType<typeof setTimeout> | undefined, movieTimer: ReturnType<typeof setTimeout> | undefined
let lastFocus: HTMLElement | null = null
function headers() { const t = localStorage.getItem('admin_token'); return t ? { Authorization: `Bearer ${t}` } : {} }
async function get(url: string, params: any = {}) { return (await axios.get(url, { headers: headers(), params })).data }
async function send(method: string, url: string, data?: any) { return (await axios({ method, url, data, headers: headers() })).data }
function message(e: any) { const d = e.response?.data?.detail; if (e.response?.status === 404) return 'API раздела недоступен. Проверьте версию Backend и маршрутизацию; данные не подменяются пустым списком.'; return typeof d === 'string' ? d : e.response?.status === 401 ? 'Сессия истекла. Войдите снова.' : 'Операция не выполнена. Повторите запрос.' }
async function act(fn: () => Promise<any>, success = 'Изменения сохранены') { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn(); notice.value = success } catch (e) { error.value = message(e) } finally { busy.value = false } }
function date(v: string | null | undefined) { return v ? new Intl.DateTimeFormat('ru-RU', { dateStyle: 'medium' }).format(new Date(v)) : '—' }
function initials(u: any) { return (u.username || u.email || '?').slice(0, 2).toUpperCase() }
function subLabel(s: any) { return !s ? 'Free' : !s.is_current ? 'Истекла / отключена' : s.status === 'trial' ? 'Пробная' : s.status === 'canceled' ? 'Отменена · доступ до срока' : 'Активна' }
async function loadUsers() { const g = ++generation; loading.value = true; try { const d = await get(crm + '/users', { q: search.value, status: status.value, login: login.value, subscription: subscription.value, offset: offset.value, limit: 25 }); if (g === generation) { users.value = d.items; total.value = d.total } } finally { if (g === generation) loading.value = false } }
async function refresh() { error.value = ''; const results = await Promise.allSettled([loadUsers(), get(crm + '/overview').then(d => overview.value = d), get(base + '/entitlements').then(d => modules.value = d), get(base + '/plans').then(d => { plans.value = d; if (!planId.value) planId.value = d.find((p: any) => p.is_active)?.id || '' }), get(base + '/promos').then(d => promos.value = d), loadSegments(), get(base + '/campaigns').then(d => campaigns.value = d), get(crm + '/genres').then(d => genres.value = d)]); const failure = results.find(r => r.status === 'rejected'); if (failure?.status === 'rejected') error.value = message(failure.reason) }
async function loadSegments() { const rows = await get(base + '/segments'); segments.value = await Promise.all(rows.map(async (s: any) => ({ ...s, count: (await send('post', base + '/segments/preview', s.criteria)).total }))) }
async function openUser(u: any) { await act(async () => { lastFocus = document.activeElement as HTMLElement; profile.value = await get(crm + '/users/' + u.id); banReason.value = profile.value.ban_reason; await nextTick(); drawer.value?.focus() }, '') }
function closeUser() { profile.value = null; lastFocus?.focus() }
async function reloadUser() { if (profile.value) profile.value = await get(crm + '/users/' + profile.value.id); await Promise.all([loadUsers(), get(crm + '/overview').then(d => overview.value = d)]) }
async function extendUser(u: any, days: number | null) { if (!planId.value) { error.value = 'Сначала выберите активный тариф.'; return }; await act(async () => { await send('post', `${crm}/users/${u.id}/subscription`, { plan_id: planId.value, days }); await reloadUser() }, days ? `Подписка продлена на ${days} дней` : 'Выдан бессрочный доступ') }
function revoke(u: any) { confirmAction.value = { title: 'Отключить подписку?', text: `Платная подписка ${u.username} прекратится сейчас. Индивидуальные права сохранятся.`, run: async () => { await send('delete', `${crm}/users/${u.id}/subscription`); await reloadUser() } } }
async function setAccount(u: any) { if (u.status === 'active' && !profile.value) { await openUser(u); return }; if (u.status === 'active' && !banReason.value.trim()) { error.value = 'Укажите причину блокировки в карточке пользователя.'; return }; confirmAction.value = { title: u.status === 'active' ? 'Заблокировать аккаунт?' : 'Восстановить доступ?', text: u.status === 'active' ? 'Все JWT будут отозваны, активные сеансы просмотра завершены.' : 'Пользователь сможет войти снова. Старые сессии не восстановятся.', run: async () => { await send('put', `${crm}/users/${u.id}/account`, { blocked: u.status === 'active', reason: banReason.value }); await reloadUser() } } }
function resetSessions() { confirmAction.value = { title: 'Сбросить все сессии?', text: 'Пользователю потребуется войти снова на всех устройствах.', run: async () => { await send('post', `${crm}/users/${profile.value.id}/reset-sessions`); await reloadUser() } } }
async function toggleRight(code: string, enabled: boolean) { await act(async () => { await send('put', `${crm}/users/${profile.value.id}/rights/${encodeURIComponent(code)}`, { enabled }); await reloadUser() }) }
function editPlan(p?: any) { plan.value = p ? { code: p.code, title: p.title, billing_period_days: p.billing_period_days, price_amount: Number(p.price_amount), currency: p.currency, is_active: p.is_active, entitlements: [...p.entitlements] } : { code: '', title: '', billing_period_days: 30, price_amount: 0, currency: 'USD', is_active: true, entitlements: [] }; showPlan.value = true }
async function savePlan() { await act(async () => { const data = { ...plan.value, code: plan.value.code || 'plan_' + Array.from(crypto.getRandomValues(new Uint8Array(6)), n => n.toString(16).padStart(2, '0')).join('') }; await send('put', base + '/plans/' + data.code, data); showPlan.value = false; await refresh() }) }
async function disablePlan(p: any) { confirmAction.value = { title: 'Отключить тариф?', text: 'Новые выдачи прекратятся. Действующие права пользователей сохранятся до конца оплаченного срока.', run: async () => { await send('put', base + '/plans/' + p.code, { code: p.code, title: p.title, billing_period_days: p.billing_period_days, price_amount: p.price_amount, currency: p.currency, is_active: false, entitlements: p.entitlements }); await refresh() } } }
async function saveModule() { await act(async () => { await send('post', crm + '/modules', moduleForm.value); showModule.value = false; moduleForm.value = { name: '', description: '' }; await refresh() }) }
async function savePromo() { await act(async () => { await send('post', base + '/promos', { ...promo.value, label: promo.value.label || promo.value.code, expires_at: new Date(promo.value.expires_at).toISOString() }); showPromo.value = false; await refresh() }) }
async function loadCatalog() { catalogRows.value = await get(crm + '/catalog', { q: catalogSearch.value, kind: catalogKind.value, offset: catalogOffset.value }) }
async function toggleContent(row: any) { await act(async () => { const d = await send('put', `${crm}/content/${row.kind}/${row.id}`, { enabled: !row.premium }); row.premium = d.premium }) }
function criteria() { const s = segment.value; const r: any = {}; if (s.activity === 'active7') r.active_within_days = 7; if (s.activity === 'inactive14') r.inactive_over_days = 14; if (s.genre) r.genre = s.genre; if (s.movie_id) r.movie_id = s.movie_id; if (s.subscription_status) r.subscription_status = s.subscription_status; if (s.can_send_telegram_msg) r.can_send_telegram_msg = true; return r }
async function previewSegment() { await act(async () => { segmentCount.value = (await send('post', base + '/segments/preview', criteria())).total }, '') }
async function saveSegment() { await act(async () => { await send('post', base + '/segments', { title: segment.value.title, criteria: criteria() }); await loadSegments() }) }
async function saveCampaign() { await act(async () => { await send('post', base + '/campaigns', { ...campaign.value, segment_id: campaign.value.segment_id || null }); campaign.value = { title: '', segment_id: '', text: '', parse_mode: 'HTML', buttons: [] }; campaigns.value = await get(base + '/campaigns') }, 'Черновик сохранён. Для отправки запустите рассылку отдельно.') }
async function queueCampaign(c: any) { await act(async () => { const p = await get(`${base}/campaigns/${c.id}/preview`); confirmAction.value = { title: 'Запустить рассылку?', text: `Кампания «${c.title}». В сегменте ${p.total} пользователей. Отправка только доступным в Telegram; действие нельзя отменить для уже доставленных сообщений.`, run: async () => { await send('post', `${base}/campaigns/${c.id}/queue`, { confirm: true, expected_audience: p.total }); await refresh() } } }, '') }
async function confirmRun() { const item = confirmAction.value; confirmAction.value = null; if (item) await act(item.run) }
function trap(event: KeyboardEvent) { if (event.key === 'Escape') { if (confirmAction.value) confirmAction.value = null; else closeUser() }; if (event.key === 'Tab' && profile.value && drawer.value && !confirmAction.value) { const all = Array.from(drawer.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')); const first = all[0], last = all[all.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() } } }
watch([search, status, login, subscription], () => { offset.value = 0; clearTimeout(searchTimer); searchTimer = setTimeout(() => { loadUsers().catch(e => error.value = message(e)) }, 250) })
watch([catalogSearch, catalogKind], () => { catalogOffset.value = 0; clearTimeout(catalogTimer); catalogTimer = setTimeout(() => loadCatalog().catch(e => error.value = message(e)), 250) })
watch(movieSearch, () => { segment.value.movie_id = ''; clearTimeout(movieTimer); const q = movieSearch.value; movieTimer = setTimeout(async () => { try { const rows = q ? await get(crm + '/catalog', { q, kind: 'movie' }) : []; if (movieSearch.value === q) movieMatches.value = rows } catch (e) { error.value = message(e) } }, 250) })
watch(tab, t => { if (t === 'access') loadCatalog().catch(e => error.value = message(e)) })
onMounted(() => { refresh(); document.addEventListener('keydown', trap) })
onBeforeUnmount(() => { clearTimeout(searchTimer); clearTimeout(catalogTimer); clearTimeout(movieTimer); document.removeEventListener('keydown', trap) })
</script>

<template>
<main class="audience" :aria-busy="busy">
  <header class="page-head"><div><p class="eyebrow">AUDIENCE · CONTROL PLANE</p><h1>Пользователи и развитие</h1><p class="muted">Аудитория, доступ к контенту и коммуникации — в одном месте.</p></div><button class="secondary" :disabled="busy || loading" @click="refresh">↻ Обновить данные</button></header>
  <nav class="tabs" aria-label="Разделы управления аудиторией"><button :class="{ selected: tab === 'users' }" @click="tab = 'users'">Пользователи</button><button :class="{ selected: tab === 'access' }" @click="tab = 'access'">Подписки, модули и контент</button><button :class="{ selected: tab === 'marketing' }" @click="tab = 'marketing'">Сегменты и рассылки</button></nav>
  <div v-if="error" role="alert" class="banner error">{{ error }} <button @click="refresh">Повторить</button></div><div v-if="notice" role="status" class="banner success">{{ notice }}</div>
  <section v-if="tab === 'users'">
    <div class="kpis"><article v-for="[key, label] in kpis" :key="key" class="kpi"><span>{{ label }}</span><strong>{{ overview ? overview[key!] : '—' }}</strong></article></div>
    <div class="panel"><div class="panel-head"><div><h2>Все пользователи <span class="count">{{ total }}</span></h2><p class="muted">Реальные аккаунты, включая администраторов. Служебные аккаунты защищены от блокировки.</p></div></div>
      <div class="filters"><label class="grow">Поиск<input v-model="search" placeholder="Имя, email или Telegram" type="search" /></label><label>Аккаунт<select v-model="status"><option value="all">Все статусы</option><option value="active">Активные</option><option value="blocked">Заблокированные</option></select></label><label>Способ входа<select v-model="login"><option value="all">Все способы</option><option value="telegram">Telegram</option><option value="password">Логин / пароль</option></select></label><label>Подписка<select v-model="subscription"><option value="all">Все подписки</option><option value="active">Действует</option><option value="free">Free · без подписок</option><option value="expired">Истекла / отключена</option></select></label></div>
      <div class="table-scroll"><table><thead><tr><th>Пользователь</th><th>Вход и аккаунт</th><th>Подписка</th><th>Активность</th><th>Действия</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><button class="person" @click="openUser(u)"><span class="avatar">{{ initials(u) }}</span><span><b>{{ u.username }}</b><small>{{ u.email?.endsWith('@telegram.invalid') ? 'Telegram-профиль' : u.email }}</small><small class="mono" :title="u.id">ID {{ u.id.slice(0, 8) }}</small></span></button></td><td><span v-if="u.telegram_id" class="badge telegram">Telegram {{ u.telegram_username ? '@' + u.telegram_username : '' }}</span><span v-if="u.password_login_available" class="badge">Логин / пароль</span><small v-if="u.telegram_id">{{ u.can_send_telegram_msg ? 'Бот разрешён' : 'Бот недоступен' }}</small><span :class="['badge', u.status === 'active' ? 'good' : 'bad']">{{ u.status === 'active' ? 'Активен' : 'Отключён' }}</span><small v-if="u.role === 'admin'">Администратор</small></td><td><b>{{ u.subscription?.title || 'Free' }}</b><small>{{ subLabel(u.subscription) }}</small><small v-if="u.subscription?.is_current">{{ u.subscription.expires_at ? 'До ' + date(u.subscription.expires_at) : 'Бессрочно' }}</small></td><td><small>Регистрация {{ date(u.created_at) }}</small><small>Визит {{ date(u.last_seen_at) }}</small><span>{{ u.activity.movies_watched }} фильмов · {{ u.activity.series_watched }} сериалов</span></td><td><div class="row-actions"><button @click="openUser(u)">Управлять</button><button :disabled="busy || !planId" @click="extendUser(u, 30)">+30 дней</button><button :disabled="busy || !u.subscription?.is_current" @click="revoke(u)">Отключить подписку</button><button :disabled="busy || u.role === 'admin'" :class="{ danger: u.status === 'active' }" @click="setAccount(u)">{{ u.status === 'active' ? 'Заблокировать' : 'Разблокировать' }}</button></div></td></tr><tr v-if="!users.length"><td colspan="5" class="empty">{{ loading ? 'Загружаем пользователей…' : error ? 'Данные не загружены. Повторите запрос.' : 'По выбранным фильтрам пользователи не найдены.' }}</td></tr></tbody></table></div>
      <footer class="pagination"><label>Тариф для быстрой выдачи<select v-model="planId"><option value="" disabled>Выберите тариф</option><option v-for="p in activePlans" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><span>{{ total ? offset + 1 : 0 }}–{{ Math.min(offset + 25, total) }} из {{ total }}</span><button :disabled="offset === 0 || loading" @click="offset -= 25; loadUsers().catch(e => error = message(e))">Назад</button><button :disabled="offset + 25 >= total || loading" @click="offset += 25; loadUsers().catch(e => error = message(e))">Далее</button></footer>
    </div>
  </section>
  <section v-if="tab === 'access'" class="stack">
    <div class="section-head"><div><h2>Модули и возможности</h2><p class="muted">Собирайте тариф из прав. Технические идентификаторы создаются автоматически.</p></div><button @click="showModule = !showModule">+ Добавить модуль / функцию</button></div>
    <form v-if="showModule" class="panel inline-form" @submit.prevent="saveModule"><label>Название<input v-model="moduleForm.name" required maxlength="200" /></label><label class="grow">Описание<input v-model="moduleForm.description" maxlength="4000" /></label><button class="primary" :disabled="busy">Добавить</button><button type="button" @click="showModule = false">Отмена</button></form>
    <div class="module-grid"><article v-for="m in modules" :key="m.code" class="module"><span class="module-icon">{{ m.code === 'content:premium' ? '🔒' : m.code === 'module:movie_radar' ? '🎯' : m.code.startsWith('quality:') ? '⚡' : '◇' }}</span><h3>{{ m.name }}</h3><p>{{ m.description }}</p><small>Настраивается в правах тарифа</small></article></div>
    <div class="section-head"><div><h2>Тарифы</h2><p class="muted">Отключение тарифа не отбирает уже выданный доступ.</p></div><button class="primary" @click="editPlan()">+ Новый тариф</button></div>
    <form v-if="showPlan" class="panel form-panel" @submit.prevent="savePlan"><h3>{{ plan.code ? 'Редактировать тариф' : 'Новый тариф' }}</h3><div class="form-grid"><label>Название<input v-model="plan.title" required maxlength="200" /></label><label>Период, дней<input v-model.number="plan.billing_period_days" type="number" min="1" max="36500" required /></label><label>Цена<input v-model.number="plan.price_amount" type="number" min="0" step="0.01" required /></label><label>Валюта<select v-model="plan.currency"><option>USD</option><option>EUR</option><option>RUB</option><option>UAH</option><option>XTR</option></select></label></div><fieldset><legend>Возможности тарифа</legend><div class="rights-grid"><label v-for="m in modules" :key="m.code" class="right-card"><input v-model="plan.entitlements" type="checkbox" :value="m.code" /><span><b>{{ m.name }}</b><small>{{ m.description }}</small></span></label></div></fieldset><div class="actions"><button class="primary" :disabled="busy">Сохранить тариф</button><button type="button" @click="showPlan = false">Отмена</button></div></form>
    <div class="plan-grid"><article v-for="p in plans" :key="p.id" class="panel plan-card"><div class="section-head"><h3>{{ p.title }}</h3><span :class="['badge', p.is_active ? 'good' : 'bad']">{{ p.is_active ? 'Активен' : 'Отключён' }}</span></div><p class="price">{{ p.price_amount }} {{ p.currency }} <small>/ {{ p.billing_period_days }} дней</small></p><ul><li v-for="code in p.entitlements" :key="code">{{ modules.find(m => m.code === code)?.name || code }}</li></ul><p v-if="!p.entitlements.length" class="muted">Права пока не добавлены</p><div class="actions"><button @click="editPlan(p)">Редактировать</button><button :disabled="busy || !p.is_active" @click="disablePlan(p)">Отключить</button></div></article></div>
    <div class="panel"><div class="panel-head section-head"><div><h2>Доступ к фильмам и сериалам</h2><p class="muted">Ограничение проверяется Backend перед выдачей токена просмотра.</p></div></div><div class="filters"><label>Каталог<select v-model="catalogKind"><option value="movie">Фильмы</option><option value="series">Сериалы</option></select></label><label class="grow">Поиск по названию<input v-model="catalogSearch" type="search" placeholder="Найдите фильм или сериал" /></label></div><div class="content-list"><div v-for="r in catalogRows" :key="r.id" class="content-row"><span><b>{{ r.title }}</b> <small>{{ r.year }}</small></span><button role="switch" :aria-checked="r.premium" :class="['access-switch', { premium: r.premium }]" :disabled="busy" @click="toggleContent(r)">{{ r.premium ? '🔒 Только Premium' : 'Всем бесплатно' }}</button></div><p v-if="!catalogRows.length" class="empty">Нет совпадений в каталоге.</p></div><footer class="pagination"><button :disabled="catalogOffset === 0" @click="catalogOffset -= 20; loadCatalog()">Назад</button><button :disabled="catalogRows.length < 20" @click="catalogOffset += 20; loadCatalog()">Далее</button></footer></div>
    <div class="panel"><div class="panel-head section-head"><h2>Промокоды</h2><button @click="showPromo = !showPromo">+ Создать промокод</button></div><form v-if="showPromo" class="form-panel" @submit.prevent="savePromo"><div class="form-grid"><label>Промокод<input v-model="promo.code" required minlength="8" maxlength="64" pattern="[A-Za-z0-9_-]+" placeholder="WELCOME2026" /></label><label>Описание<input v-model="promo.label" maxlength="100" /></label><label>Тариф<select v-model="promo.plan_id" required><option value="" disabled>Выберите тариф</option><option v-for="p in activePlans" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><label>Доступ, дней<input v-model.number="promo.duration_days" type="number" min="1" max="36500" required /></label><label>Лимит активаций<input v-model.number="promo.max_redemptions" type="number" min="1" max="1000000" required /></label><label>Принимать до<input v-model="promo.expires_at" type="datetime-local" required /></label></div><button class="primary" :disabled="busy">Создать</button></form><div class="table-scroll"><table><thead><tr><th>Код / описание</th><th>Что выдаёт</th><th>Период</th><th>Активации</th><th>Статус</th><th></th></tr></thead><tbody><tr v-for="p in promos" :key="p.id"><td><b>{{ p.code || p.label }}</b><small v-if="p.code">{{ p.label }}</small></td><td>{{ plans.find(x => x.id === p.plan_id)?.title || modules.find(x => x.code === p.entitlement_code)?.name }}</td><td>{{ p.duration_days }} дней</td><td>{{ p.redemption_count }} / {{ p.max_redemptions }}</td><td>{{ p.is_active ? 'Активен' : 'Отключён' }}<small>До {{ date(p.expires_at) }}</small></td><td><button :disabled="busy || !p.is_active" @click="act(async () => { await send('post', base + '/promos/' + p.id + '/disable'); await refresh() })">Деактивировать</button></td></tr><tr v-if="!promos.length"><td colspan="6" class="empty">Промокодов пока нет.</td></tr></tbody></table></div></div>
  </section>
  <section v-if="tab === 'marketing'" class="stack">
    <div class="two-col"><form class="panel form-panel" @submit.prevent="saveSegment"><h2>Конструктор сегмента</h2><p class="muted">Условия активности, подписки и Telegram сочетаются. Фильм или жанр — любое совпадение.</p><label>Название сегмента<input v-model="segment.title" required placeholder="Например, вернём любителей фантастики" maxlength="200" /></label><div class="form-grid"><label>Активность<select v-model="segment.activity"><option value="">Любая</option><option value="active7">Активны за 7 дней</option><option value="inactive14">Не заходили более 14 дней</option></select></label><label>Подписка<select v-model="segment.subscription_status"><option value="">Любая</option><option value="free">Free</option><option value="trial">Пробная</option><option value="active_paid">Активная платная</option><option value="expired">Истекла</option><option value="churned">Ушедшие</option></select></label></div><label>Интерес: жанр<select v-model="segment.genre"><option value="">Любой жанр</option><option v-for="g in genres" :key="g.slug" :value="g.slug">{{ g.name }}</option></select></label><label>Интерес: просмотренный фильм<input v-model="movieSearch" type="search" placeholder="Начните вводить название фильма" autocomplete="off" /></label><div v-if="movieMatches.length" class="suggestions" aria-label="Найденные фильмы"><button v-for="m in movieMatches" :key="m.id" type="button" @click="segment.movie_id = m.id; movieMatches = []">{{ m.title }} · {{ m.year }}</button></div><small v-if="segment.movie_id" class="good-text">✓ Фильм выбран</small><label class="check"><input v-model="segment.can_send_telegram_msg" type="checkbox" /> Только доступные в Telegram</label><div class="actions"><button type="button" :disabled="busy" @click="previewSegment">Посчитать аудиторию</button><button class="primary" :disabled="busy">Сохранить сегмент</button></div><p v-if="segmentCount !== null" class="result-count">Подходят {{ segmentCount }} пользователей</p></form>
      <div class="panel form-panel"><h2>Сохранённые сегменты</h2><div v-for="s in segments" :key="s.id" class="segment-row"><div><b>{{ s.title }}</b><small>{{ s.criteria.can_send_telegram_msg ? 'Telegram доступен' : 'Все способы связи' }}</small></div><span class="segment-number">{{ s.count }} <small>польз.</small></span></div><p v-if="!segments.length" class="empty">Сохраните первый сегмент, чтобы использовать его в рассылке.</p></div></div>
    <div class="two-col composer"><form class="panel form-panel" @submit.prevent="saveCampaign"><h2>Новая Telegram-рассылка</h2><label>Название кампании<input v-model="campaign.title" required maxlength="200" placeholder="Внутреннее название" /></label><label>Аудитория<select v-model="campaign.segment_id"><option value="">Все активные зрители</option><option v-for="s in segments" :key="s.id" :value="s.id">{{ s.title }} · {{ s.count }} пользователей</option></select></label><label>Формат сообщения<select v-model="campaign.parse_mode"><option>HTML</option><option>MarkdownV2</option></select></label><label>Сообщение<textarea v-model="campaign.text" required maxlength="3500" rows="7" placeholder="Расскажите зрителям о новинках…"></textarea></label><fieldset><legend>Кнопки под сообщением</legend><div v-for="(b, i) in campaign.buttons" :key="i" class="button-editor"><label>Текст кнопки<input v-model="b.text" required maxlength="64" placeholder="Смотреть новинки" /></label><label>URL ссылки<input v-model="b.url" type="url" required placeholder="https://watch.scenrix.com/" /></label><button type="button" :aria-label="'Удалить кнопку ' + (Number(i) + 1)" @click="campaign.buttons.splice(i, 1)">×</button></div><button type="button" :disabled="campaign.buttons.length >= 8" @click="campaign.buttons.push({ text: '', url: '' })">+ Добавить кнопку</button></fieldset><button class="primary" :disabled="busy">Сохранить черновик</button><small>Сохранение не запускает отправку. Перед запуском покажем количество получателей.</small></form><aside class="preview-panel"><p class="eyebrow">ПРЕДПРОСМОТР В TELEGRAM</p><div class="telegram-preview"><header><span class="avatar">К</span><div><b>Киносота</b><small>бот · сообщение зрителю</small></div></header><div class="bubble"><p>{{ campaign.text || 'Здесь появится ваше сообщение' }}</p><time>12:30 ✓✓</time></div><div class="preview-buttons"><span v-for="(b, i) in campaign.buttons" :key="i">{{ b.text || 'Текст кнопки' }} ↗</span></div></div><p class="muted">Макет показывает текст и расположение кнопок. Разметку {{ campaign.parse_mode }} и ссылки проверяйте тестовой отправкой себе; HTML здесь не исполняется.</p></aside></div>
    <div class="panel"><div class="panel-head"><h2>Кампании</h2><p class="muted">Тест отправляется только в Telegram текущего администратора, если он привязан к аккаунту.</p></div><div class="table-scroll"><table><thead><tr><th>Кампания</th><th>Статус</th><th>В сегменте</th><th>Отправлено</th><th>Заблокировали бота</th><th>Переходы</th><th>Управление</th></tr></thead><tbody><tr v-for="c in campaigns" :key="c.id"><td><b>{{ c.title }}</b><small>{{ date(c.created_at) }}</small></td><td>{{ ({ draft: 'Черновик', queued: 'В очереди', sending: 'Отправляется', completed: 'Завершена', canceled: 'Остановлена' } as any)[c.status] }}</td><td>{{ c.audience_count }}</td><td>{{ c.deliveries.sent || 0 }}</td><td>{{ c.deliveries.blocked || 0 }}</td><td>{{ c.clicks }}</td><td><div class="row-actions"><button :disabled="busy" @click="act(() => send('post', `${crm}/campaigns/${c.id}/test`), 'Тестовое сообщение отправлено в ваш Telegram')">Тестовая отправка себе</button><button :disabled="busy || c.status !== 'draft'" @click="queueCampaign(c)">Запустить рассылку</button><button :disabled="busy || c.status !== 'draft'" @click="confirmAction = { title: 'Удалить черновик?', text: c.title, run: async () => { await send('delete', `${crm}/campaigns/${c.id}`); await refresh() } }">Удалить черновик</button></div></td></tr><tr v-if="!campaigns.length"><td colspan="7" class="empty">Рассылок пока нет. Создайте черновик выше.</td></tr></tbody></table></div></div>
  </section>
  <div v-if="profile" class="drawer-backdrop" @click.self="closeUser"><aside ref="drawer" class="drawer" role="dialog" aria-modal="true" aria-labelledby="profile-title" tabindex="-1"><header class="drawer-head"><div class="person"><span class="avatar large">{{ initials(profile) }}</span><div><h2 id="profile-title">{{ profile.username }}</h2><small>{{ profile.email }}</small></div></div><button aria-label="Закрыть профиль" @click="closeUser">×</button></header><div class="drawer-body"><div v-if="error" role="alert" class="banner error">{{ error }}</div><p class="mono muted">{{ profile.id }}</p><div class="mini-stats"><div><b>{{ profile.activity.movies_watched }}</b><small>Фильмов</small></div><div><b>{{ profile.activity.series_watched }}</b><small>Сериалов</small></div><div><b>{{ date(profile.last_seen_at) }}</b><small>Последний визит</small></div></div><section><h3>Профиль и регистрация</h3><dl><dt>Дата регистрации</dt><dd>{{ date(profile.created_at) }}</dd><dt>Источник / UTM / ref</dt><dd>{{ profile.acquisition_source || 'Не зафиксирован' }}</dd><dt>Telegram</dt><dd>{{ profile.telegram_username ? '@' + profile.telegram_username : profile.telegram_id || 'Не привязан' }}</dd><dt>Любимые жанры</dt><dd>{{ profile.activity.favorite_genres.map((g: any) => typeof g === 'string' ? (genres.find(x => x.slug === g)?.name || g) : (g.genre || g.slug || g.name)).join(', ') || 'Пока нет данных' }}</dd></dl></section><section><h3>Подписка</h3><p><b>{{ profile.subscription?.title || 'Free' }}</b> · {{ subLabel(profile.subscription) }}<small v-if="profile.subscription?.is_current">{{ profile.subscription.expires_at ? 'До ' + date(profile.subscription.expires_at) : 'Бессрочно' }}</small></p><label>Тариф<select v-model="planId"><option value="" disabled>Выберите тариф</option><option v-for="p in activePlans" :key="p.id" :value="p.id">{{ p.title }}</option></select></label><div class="quick-grants"><button v-for="days in [7, 30, 365]" :key="days" :disabled="busy || !planId" @click="extendUser(profile, days)">+{{ days === 365 ? '1 год' : days + ' дней' }}</button><button :disabled="busy || !planId" @click="extendUser(profile, null)">Бессрочно</button></div><button class="danger" :disabled="busy || !profile.subscription?.is_current" @click="revoke(profile)">Прекратить подписку сейчас</button></section><section><h3>Индивидуальные права</h3><p class="muted">Выключатель может запретить право даже из тарифа. Включение выдаёт отдельный бессрочный доступ.</p><label v-for="m in modules" :key="m.code" class="right-card"><input type="checkbox" :checked="profile.entitlements.includes(m.code)" :disabled="busy" @change="toggleRight(m.code, ($event.target as HTMLInputElement).checked)" /><span><b>{{ m.name }}</b><small>{{ m.description }}</small></span></label></section><section><h3>Последние просмотры</h3><div v-for="(v, i) in profile.recent_views" :key="i" class="content-row"><span>{{ v.kind === 'movie' ? 'Фильм' : 'Сериал' }} · {{ v.title }}</span><small>{{ date(v.seen_at) }}</small></div><p v-if="!profile.recent_views.length" class="muted">Зафиксированных просмотров пока нет.</p></section><section><h3>Сессии и устройства</h3><p class="muted">{{ profile.sessions_note }}</p><div v-for="(s, i) in profile.sessions" :key="i" class="session"><b>{{ s.user_agent || 'Устройство не определено' }}</b><small>Последний запрос {{ date(s.last_seen_at) }} · до {{ date(s.expires_at) }}</small></div><p v-if="!profile.sessions.length" class="muted">Нет зафиксированных активных сессий.</p><button :disabled="busy || profile.role === 'admin'" @click="resetSessions">Сбросить все сессии</button></section><section><h3>Управление аккаунтом</h3><span :class="['badge', profile.status === 'active' ? 'good' : 'bad']">{{ profile.status === 'active' ? 'Активен' : 'Заблокирован' }}</span><label>Причина блокировки<textarea v-model="banReason" rows="2" maxlength="1000" placeholder="Обязательна при блокировке"></textarea></label><button :disabled="busy || profile.role === 'admin'" :class="{ danger: profile.status === 'active' }" @click="setAccount(profile)">{{ profile.status === 'active' ? 'Отключить аккаунт (Бан)' : 'Восстановить доступ' }}</button><small v-if="profile.role === 'admin'">Аккаунт администратора защищён от случайной блокировки.</small></section></div></aside></div>
  <div v-if="confirmAction" class="confirm-backdrop"><section role="alertdialog" aria-modal="true" aria-labelledby="confirm-title" class="confirm"><h2 id="confirm-title">{{ confirmAction.title }}</h2><p>{{ confirmAction.text }}</p><div class="actions"><button autofocus @click="confirmAction = null">Отмена</button><button class="primary" :disabled="busy" @click="confirmRun">Подтвердить</button></div></section></div>
</main>
